jobdb_result_t basalt_execution_get(jobdb_t *db, uint64_t id, basalt_execution_view_t *out) { jobdb_execution_t e; jobdb_result_t r; if (!out) return JOBDB_ERR_INVALID_ARGUMENT; r=jobdb_execution_get(db,id,&e); if(r!=JOBDB_OK)return r; out->execution_id=e.execution_id; out->job_definition_id=e.job_definition_id; out->schedule_id=e.schedule_id; out->workflow_id=e.workflow_id; out->state=(uint32_t)e.state; out->payload_version=0; out->created_at=e.created_at; out->eligible_at=e.eligible_at; out->started_at=e.started_at; out->finished_at=e.finished_at; out->priority=e.priority; out->attempt=e.attempt; out->max_attempts=e.max_attempts; out->revision=e.revision; memcpy(out->worker_instance_id,e.worker_instance_id,16); out->lease_expires_at=e.lease_expires_at; out->fencing_token=e.fencing_token; return JOBDB_OK; }
jobdb_result_t basalt_execution_list(jobdb_t *db, uint64_t *ids, size_t capacity, size_t *out_count) { return jobdb_list_record_ids(db, 3, ids, capacity, out_count); }
jobdb_result_t basalt_execution_cancel(jobdb_t *db, uint64_t id, uint64_t expected) { return jobdb_execution_finalize_unleased(db,id,expected,JOBDB_EXEC_CANCELLED,0,0); }
jobdb_result_t basalt_execution_requeue(jobdb_t *db, uint64_t id, uint64_t expected) { jobdb_execution_t e; jobdb_result_t r=jobdb_execution_get(db,id,&e); if(r!=JOBDB_OK)return r; return e.state==JOBDB_EXEC_PAUSED ? jobdb_execution_resume_paused(db,id,expected,NULL) : jobdb_execution_requeue_admin(db,id,expected,NULL); }
jobdb_result_t basalt_ledger_get(jobdb_t *db, uint64_t id, basalt_ledger_view_t *out) { jobdb_ledger_entry_t e; jobdb_result_t r; if (!out) return JOBDB_ERR_INVALID_ARGUMENT; r=jobdb_ledger_get(db,id,&e); if(r!=JOBDB_OK)return r; out->execution_id=e.execution_id;out->job_definition_id=e.job_definition_id;out->schedule_id=e.schedule_id;out->workflow_id=e.workflow_id;out->started_at=e.started_at;out->finished_at=e.finished_at;out->duration=e.duration;out->attempt=e.attempt;out->final_state=(uint32_t)e.final_state;out->result_code=e.result_code;out->error_code=e.error_code;return JOBDB_OK; }
jobdb_result_t basalt_ledger_list(jobdb_t *db, uint64_t *ids, size_t capacity, size_t *out_count) { return jobdb_list_record_ids(db, 4, ids, capacity, out_count); }
jobdb_result_t basalt_stats_get(jobdb_t *db, basalt_stats_view_t *out) { jobdb_stats_t s; jobdb_result_t r;if(!out)return JOBDB_ERR_INVALID_ARGUMENT;r=jobdb_get_stats(db,&s);if(r!=JOBDB_OK)return r;out->submitted_total=s.submitted_total;out->started_total=s.started_total;out->completed_total=s.completed_total;out->failed_total=s.failed_total;out->retried_total=s.retried_total;out->cancelled_total=s.cancelled_total;out->dead_total=s.dead_total;out->recovered_total=s.recovered_total;return JOBDB_OK; }
jobdb_result_t basalt_db_health(jobdb_t *db) { return jobdb_health(db); }
static void schedule_view_from_native(const jobdb_schedule_t *in, basalt_schedule_view_t *out) { out->schedule_id=in->schedule_id;out->job_definition_id=in->job_definition_id;out->schedule_type=in->schedule_type;out->enabled=in->enabled;out->timezone_reference=in->timezone_reference;out->interval=in->interval;out->interval_mode=in->interval_mode;out->catch_up_max=in->catch_up_max;out->start_at=in->start_at;out->end_at=in->end_at;out->last_fire_at=in->last_fire_at;out->next_fire_at=in->next_fire_at;out->occurrence_count=in->occurrence_count;out->max_occurrences=in->max_occurrences;out->misfire_policy=in->misfire_policy;out->overlap_policy=in->overlap_policy;out->revision=in->revision; }
jobdb_result_t basalt_schedule_create(jobcore_t *core,uint64_t id,uint64_t type,uint32_t schedule_type,int64_t first,int64_t interval,uint32_t interval_mode,uint64_t max_occurrences,const void*payload,uint32_t payload_size,uint32_t version,const char*cron,const char*timezone,uint32_t misfire,uint32_t overlap,uint32_t catch_up){jobcore_schedule_spec_t s;memset(&s,0,sizeof s);s.schedule_id=id;s.job_type=type;s.type=(jobcore_schedule_type_t)schedule_type;s.first_fire_at=first;s.interval=interval;s.interval_mode=(jobcore_interval_mode_t)interval_mode;s.max_occurrences=max_occurrences;s.payload=payload;s.payload_size=payload_size;s.payload_version=version;s.cron_expression=cron;s.timezone=timezone;s.misfire_policy=(jobcore_misfire_policy_t)misfire;s.overlap_policy=(jobcore_overlap_policy_t)overlap;s.catch_up_max=catch_up;return jobcore_schedule_create(core,&s);}
jobdb_result_t basalt_schedule_create_v2(jobcore_t *core,uint64_t id,uint64_t type,uint32_t schedule_type,int64_t first,int64_t end,int64_t interval,uint32_t interval_mode,uint64_t max_occurrences,const void*payload,uint32_t payload_size,uint32_t version,const char*cron,const char*timezone,uint32_t misfire,uint32_t overlap,uint32_t catch_up){jobcore_schedule_spec_t s;memset(&s,0,sizeof s);s.schedule_id=id;s.job_type=type;s.type=(jobcore_schedule_type_t)schedule_type;s.first_fire_at=first;s.interval=interval;s.interval_mode=(jobcore_interval_mode_t)interval_mode;s.max_occurrences=max_occurrences;s.payload=payload;s.payload_size=payload_size;s.payload_version=version;s.cron_expression=cron;s.timezone=timezone;s.misfire_policy=(jobcore_misfire_policy_t)misfire;s.overlap_policy=(jobcore_overlap_policy_t)overlap;s.catch_up_max=catch_up;return jobcore_schedule_create_ex(core,&s,end);}
jobdb_result_t basalt_schedule_get(jobcore_t*core,uint64_t id,basalt_schedule_view_t*out){jobdb_schedule_t s;jobdb_result_t r;if(!out)return JOBDB_ERR_INVALID_ARGUMENT;r=jobcore_schedule_get(core,id,&s);if(r==JOBDB_OK)schedule_view_from_native(&s,out);return r;}
jobdb_result_t basalt_schedule_list(jobcore_t*core,uint64_t*ids,size_t capacity,size_t*out_count){basalt_storage_t*storage=jobcore_storage(core);if(!storage)return JOBDB_ERR_INVALID_ARGUMENT;return basalt_storage_list_record_ids(storage,2,ids,capacity,out_count);}
jobdb_result_t basalt_schedule_update(jobcore_t*core,const basalt_schedule_view_t*in,uint64_t expected){jobdb_schedule_t s;if(!in)return JOBDB_ERR_INVALID_ARGUMENT;memset(&s,0,sizeof s);s.schedule_id=in->schedule_id;s.job_definition_id=in->job_definition_id;s.schedule_type=in->schedule_type;s.enabled=in->enabled;s.timezone_reference=in->timezone_reference;s.interval=in->interval;s.interval_mode=in->interval_mode;s.catch_up_max=in->catch_up_max;s.start_at=in->start_at;s.end_at=in->end_at;s.last_fire_at=in->last_fire_at;s.next_fire_at=in->next_fire_at;s.occurrence_count=in->occurrence_count;s.max_occurrences=in->max_occurrences;s.misfire_policy=in->misfire_policy;s.overlap_policy=in->overlap_policy;s.revision=in->revision;return jobcore_schedule_update(core,&s,expected);}
jobdb_result_t basalt_schedule_pause(jobcore_t*core,uint64_t id,uint64_t expected){return jobcore_schedule_pause(core,id,expected);} jobdb_result_t basalt_schedule_resume(jobcore_t*core,uint64_t id,uint64_t expected){return jobcore_schedule_resume(core,id,expected);} jobdb_result_t basalt_schedule_remove(jobcore_t*core,uint64_t id,uint64_t expected){return jobcore_schedule_remove(core,id,expected);}
