jobdb_result_t basalt_core_enqueue(jobcore_t *core, uint64_t job_type, const void *payload, uint32_t payload_size, uint32_t payload_version, int64_t now, uint32_t max_attempts, uint64_t *out_execution_id) { return jobcore_enqueue(core, job_type, payload, payload_size, payload_version, now, max_attempts, out_execution_id); }
jobdb_result_t basalt_core_enqueue_retry(jobcore_t *core, uint64_t job_type, const void *payload, uint32_t payload_size, uint32_t payload_version, int64_t now, const basalt_retry_spec_v1_t *retry, uint64_t *out_execution_id) { jobcore_retry_spec_t r; if(!retry)return JOBDB_ERR_INVALID_ARGUMENT; r.policy=(jobcore_retry_policy_t)retry->policy;r.max_attempts=retry->max_attempts;r.initial_delay=retry->initial_delay;r.max_delay=retry->max_delay;r.backoff_factor=retry->backoff_factor;r.jitter=retry->jitter;return jobcore_enqueue_with_retry(core,job_type,payload,payload_size,payload_version,now,&r,out_execution_id); }
jobdb_result_t basalt_core_enqueue_idempotent(jobcore_t *core, const char *key, uint64_t job_type, const void *payload, uint32_t payload_size, uint32_t payload_version, int64_t now, uint32_t max_attempts, uint64_t *out_execution_id) { return jobcore_enqueue_idempotent(core,key,job_type,payload,payload_size,payload_version,now,max_attempts,out_execution_id); }
jobdb_result_t basalt_core_enqueue_idempotent_retry(jobcore_t *core,const char *key,uint64_t job_type,const void *payload,uint32_t payload_size,uint32_t payload_version,int64_t now,const basalt_retry_spec_v1_t *retry,uint64_t *out_execution_id){jobcore_retry_spec_t r;if(!retry)return JOBDB_ERR_INVALID_ARGUMENT;r.policy=(jobcore_retry_policy_t)retry->policy;r.max_attempts=retry->max_attempts;r.initial_delay=retry->initial_delay;r.max_delay=retry->max_delay;r.backoff_factor=retry->backoff_factor;r.jitter=retry->jitter;return jobcore_enqueue_idempotent_with_retry(core,key,job_type,payload,payload_size,payload_version,now,&r,out_execution_id);}
jobdb_result_t basalt_core_schedule_create(jobcore_t *core, const jobcore_schedule_spec_t *spec) { return jobcore_schedule_create(core, spec); }
jobdb_result_t basalt_core_workflow_submit(jobcore_t *core, uint64_t workflow_id, const basalt_workflow_node_v1_t *nodes, uint32_t count, uint32_t policy, int64_t now) { jobcore_workflow_node_t converted[128]; uint32_t i,j; if(!nodes||count>128)return JOBDB_ERR_INVALID_ARGUMENT;memset(converted,0,sizeof converted);for(i=0;i<count;i++){converted[i].node_id=nodes[i].node_id;converted[i].job_type=nodes[i].job_type;converted[i].payload=nodes[i].payload;converted[i].payload_size=nodes[i].payload_size;converted[i].payload_version=nodes[i].payload_version;converted[i].dependency_count=nodes[i].dependency_count;for(j=0;j<8;j++)converted[i].dependencies[j]=nodes[i].dependencies[j];}return jobcore_workflow_submit(core,workflow_id,converted,count,(jobcore_dependency_policy_t)policy,now); }
jobdb_result_t basalt_workflow_get(jobcore_t *core,uint64_t id,basalt_workflow_status_v1_t*out){jobcore_workflow_status_t s;jobdb_result_t r;if(!out)return JOBDB_ERR_INVALID_ARGUMENT;r=jobcore_workflow_get(core,id,&s);if(r==JOBDB_OK)memcpy(out,&s,sizeof *out);return r;}
jobdb_result_t basalt_workflow_cancel(jobcore_t *core,uint64_t id){return jobcore_workflow_cancel(core,id);}
jobdb_result_t basalt_management_record_create(jobcore_t *core,uint32_t type,uint64_t id,const void *payload,uint32_t size){basalt_storage_t *storage=jobcore_storage(core);if(!storage)return JOBDB_ERR_INVALID_ARGUMENT;return basalt_storage_record_create(storage,type,id,payload,size);}
jobdb_result_t basalt_management_record_upsert(jobcore_t *core,uint32_t type,uint64_t id,const void *payload,uint32_t size){basalt_storage_t *storage=jobcore_storage(core);jobdb_record_t record={0};jobdb_result_t result;if(!storage)return JOBDB_ERR_INVALID_ARGUMENT;result=basalt_storage_record_get(storage,type,id,&record);if(result==JOBDB_ERR_NOT_FOUND)return basalt_storage_record_create(storage,type,id,payload,size);if(result!=JOBDB_OK)return result;result=basalt_storage_record_update(storage,type,id,record.revision,payload,size,NULL);basalt_storage_record_free(storage,&record);return result;}
jobdb_result_t basalt_management_record_update(jobcore_t *core,uint32_t type,uint64_t id,uint64_t revision,const void *payload,uint32_t size){basalt_storage_t *storage=jobcore_storage(core);if(!storage)return JOBDB_ERR_INVALID_ARGUMENT;return basalt_storage_record_update(storage,type,id,revision,payload,size,NULL);}
jobdb_result_t basalt_management_record_get(jobcore_t *core,uint32_t type,uint64_t id,void *payload,uint32_t capacity,uint32_t *out_size){basalt_storage_t *storage=jobcore_storage(core);jobdb_record_t record={0};jobdb_result_t result;if(!storage||!out_size||(capacity&&!payload))return JOBDB_ERR_INVALID_ARGUMENT;result=basalt_storage_record_get(storage,type,id,&record);if(result!=JOBDB_OK)return result;*out_size=record.payload_size;if(record.payload_size>capacity){basalt_storage_record_free(storage,&record);return JOBDB_ERR_LIMIT;}if(record.payload_size)memcpy(payload,record.payload,record.payload_size);basalt_storage_record_free(storage,&record);return JOBDB_OK;}
jobdb_result_t basalt_management_record_list(jobcore_t *core,uint32_t type,uint64_t *ids,size_t capacity,size_t*out_count){basalt_storage_t *storage=jobcore_storage(core);if(!storage)return JOBDB_ERR_INVALID_ARGUMENT;return basalt_storage_list_record_ids(storage,type,ids,capacity,out_count);}
